57	  for (const [name, value] of Object.entries(params)) {
58	    if (typeof value === "string" || typeof value === "number") plainParams[name] = value;
59	  }
60	  const template = resolveTemplate(key, plainParams, locale);
61	  const nodes: ReactNode[] = [];
62	  let cursor = 0;
63	  let index = 0;
64	  for (const match of template.matchAll(RICH_TOKEN)) {
65	    const start = match.index ?? 0;
66	    if (start > cursor) nodes.push(template.slice(cursor, start));
67	    const [whole, tag, inner, name] = match;
68	    if (tag) {
69	      const render = params[tag];
70	      const chunks = interpolate(inner, plainParams, locale);
71	      nodes.push(
72	        createElement(
73	          Fragment,
74	          { key: index },
75	          typeof render === "function" ? render(chunks) : chunks,
76	        ),
77	      );
78	    } else if (name) {
79	      const value = params[name];
80	      let node: ReactNode = whole;
81	      if (typeof value === "number") node = formatNumber(value, undefined, locale);
82	      else if (value !== undefined && value !== null && typeof value !== "function") node = value;
83	      nodes.push(createElement(Fragment, { key: index }, node));
