251	      strict: descriptor.strict ?? true,
252	      needsApproval: descriptor.requiresApproval ?? false,
253	      // Host execution failures are terminal, but model-generated argument
254	      // mistakes remain model-visible so the SDK can self-correct them.
255	      errorFunction: (_context: unknown, error: unknown) => {
