import { createAssistantMessageEventStream, Type } from "@earendil-works/pi-ai";
const model = { id: "host-model", name: "Host", api: "openai-completions", provider: "host", baseUrl: "rpc://host",
  reasoning: true, input: ["text"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 128000, maxTokens: 4096 };
let call = 0;
const usage = { input: 10, output: 5, cacheRead: 0, cacheWrite: 0, totalTokens: 15, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
function streamFn(m, context, options) {
  const s = createAssistantMessageEventStream();
  const n = ++call;
  (async () => {
    await new Promise(r => setTimeout(r, 10)); // simulated RPC to host
    const base = { role: "assistant", api: m.api, provider: m.provider, model: m.id, usage, timestamp: Date.now() };
    if (n === 1) {
      const tc = { type: "toolCall", id: "c1", name: "host_tool", arguments: { q: "x" } };
      const msg = { ...base, content: [{ type: "thinking", thinking: "hmm" }, tc], stopReason: "toolUse" };
      s.push({ type: "start", partial: msg });
      s.push({ type: "thinking_delta", contentIndex: 0, delta: "hmm", partial: msg });
      s.push({ type: "toolcall_end", contentIndex: 1, toolCall: tc, partial: msg });
      s.push({ type: "done", reason: "toolUse", message: msg });
    } else {
      const msg = { ...base, content: [{ type: "text", text: "done" }], stopReason: "stop" };
      s.push({ type: "start", partial: msg });
      s.push({ type: "text_delta", contentIndex: 0, delta: "done", partial: msg });
      s.push({ type: "done", reason: "stop", message: msg });
    }
    console.log("ctx roles seen by streamFn:", context.messages.map(x => x.role).join(","));
  })();
  return s;
}
const tool = { name: "host_tool", label: "Host tool", description: "rpc", parameters: Type.Object({ q: Type.String() }),
  execute: async (id, params, signal) => { await new Promise(r => setTimeout(r, 200)); return { content: [{ type: "text", text: "result for " + params.q }], details: {} }; } };
const agent = new Agent({ initialState: { systemPrompt: "sys", model, tools: [tool] }, streamFn });
agent.subscribe(e => console.log("event", e.type, e.assistantMessageEvent?.type ?? ""));
await agent.prompt("hi");
const saved = JSON.stringify(agent.state.messages);
console.log("transcript roles:", agent.state.messages.map(m => m.role).join(","), "bytes", saved.length);
const agent2 = new Agent({ initialState: { model, tools: [tool], messages: JSON.parse(saved) }, streamFn });
await agent2.prompt("again");
console.log("resumed roles:", agent2.state.messages.map(m => m.role).join(","));
EOF
node app.mjs 2>&1 | tail -30

